import 'package:flutter/material.dart';import 'package:flutter_map/flutter_map.dart';import 'package:latlong2/latlong.dart';import '../theme/app_theme.dart';import '../services/entry_service.dart';import '../services/journal_service.dart';import '../models/entry.dart';import '../models/journal.dart';class MapScreen extends StatefulWidget {  const MapScreen({super.key});  @override  State<MapScreen> createState() => _MapScreenState();}class _MapScreenState extends State<MapScreen> {  int _selectedTab = 0;  @override  Widget build(BuildContext context) {    return SafeArea(      child: Column(        children: [          Padding(            padding: const EdgeInsets.fromLTRB(24, 24, 24, 0),            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                const Text('Harita', style: TextStyle(fontSize: 24, fontWeight: FontWeight.w500, color: AppTheme.textPrimary)),                const SizedBox(height: 16),                Row(                  children: [                    _buildTab('Haritam', 0),                    const SizedBox(width: 8),                    _buildTab('Keşfet', 1),                  ],                ),              ],            ),          ),          const SizedBox(height: 16),          Expanded(            child: _selectedTab == 0                ? const MyMapTab()                : const ExploreMapTab(),          ),        ],      ),    );  }  Widget _buildTab(String label, int index) {    final isSelected = _selectedTab == index;    return GestureDetector(      onTap: () => setState(() => _selectedTab = index),      child: Container(        padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 8),        decoration: BoxDecoration(          color: isSelected ? AppTheme.terracotta : Colors.white,          borderRadius: BorderRadius.circular(20),          border: Border.all(color: isSelected ? AppTheme.terracotta : AppTheme.border),        ),        child: Text(          label,          style: TextStyle(fontSize: 13, fontWeight: FontWeight.w500, color: isSelected ? Colors.white : AppTheme.textSecondary),        ),      ),    );  }}class MyMapTab extends StatefulWidget {  const MyMapTab({super.key});  @override  State<MyMapTab> createState() => _MyMapTabState();}class _MyMapTabState extends State<MyMapTab> {  List<EntryWithJournal> _locations = [];  bool _isLoading = true;  final MapController _mapController = MapController();  double _zoom = 5;  @override  void initState() {    super.initState();    _loadLocations();  }  Future<void> _loadLocations() async {    try {      final journals = await JournalService.getJournals();      List<EntryWithJournal> locations = [];      for (final journal in journals) {        final entries = await EntryService.getEntries(journal.id);        for (final entry in entries) {          if (entry.lat != null && entry.lng != null) {            locations.add(EntryWithJournal(entry: entry, journal: journal));          }        }      }      setState(() {        _locations = locations;        _isLoading = false;      });    } catch (e) {      setState(() => _isLoading = false);    }  }  void _zoomIn() {    _zoom = (_zoom + 1).clamp(1, 18);    _mapController.move(_mapController.camera.center, _zoom);  }  void _zoomOut() {    _zoom = (_zoom - 1).clamp(1, 18);    _mapController.move(_mapController.camera.center, _zoom);  }  @override  Widget build(BuildContext context) {    if (_isLoading) return const Center(child: CircularProgressIndicator(color: AppTheme.terracotta));    return Stack(      children: [        FlutterMap(          mapController: _mapController,          options: MapOptions(            initialCenter: _locations.isNotEmpty                ? LatLng(_locations.first.entry.lat!, _locations.first.entry.lng!)                : LatLng(41.0082, 28.9784),            initialZoom: _zoom,            onPositionChanged: (position, hasGesture) {              if (hasGesture) _zoom = position.zoom ?? _zoom;            },          ),          children: [            TileLayer(              urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',              userAgentPackageName: 'com.memorylane',            ),            MarkerLayer(              markers: _locations.map((item) => Marker(                point: LatLng(item.entry.lat!, item.entry.lng!),                width: 40,                height: 40,                child: GestureDetector(                  onTap: () => _showEntryInfo(context, item),                  child: Container(                    decoration: BoxDecoration(                      color: AppTheme.terracotta,                      borderRadius: BorderRadius.circular(20),                      boxShadow: [BoxShadow(color: AppTheme.terracotta.withOpacity(0.4), blurRadius: 8, offset: const Offset(0, 2))],                    ),                    child: const Icon(Icons.location_on, color: Colors.white, size: 20),                  ),                ),              )).toList(),            ),          ],        ),        if (_locations.isEmpty)          Center(            child: Container(              margin: const EdgeInsets.all(24),              padding: const EdgeInsets.all(24),              decoration: BoxDecoration(                color: Colors.white,                borderRadius: BorderRadius.circular(16),                boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 10)],              ),              child: Column(                mainAxisSize: MainAxisSize.min,                children: [                  Icon(Icons.map_outlined, size: 48, color: AppTheme.textSecondary.withOpacity(0.4)),                  const SizedBox(height: 12),                  const Text('Henüz konum eklenmedi', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w500, color: AppTheme.textPrimary)),                  const SizedBox(height: 8),                  Text('Sayfa eklerken konum ekle', style: TextStyle(fontSize: 13, color: AppTheme.textSecondary)),                ],              ),            ),          ),        Positioned(          bottom: 80,          right: 16,          child: Column(            children: [              _buildZoomButton(Icons.add, _zoomIn),              const SizedBox(height: 8),              _buildZoomButton(Icons.remove, _zoomOut),            ],          ),        ),        Positioned(          bottom: 16,          right: 16,          child: Container(            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),            decoration: BoxDecoration(              color: Colors.white,              borderRadius: BorderRadius.circular(20),              boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 8)],            ),            child: Text('${_locations.length} yer', style: TextStyle(fontSize: 13, color: AppTheme.textSecondary, fontWeight: FontWeight.w500)),          ),        ),      ],    );  }  Widget _buildZoomButton(IconData icon, VoidCallback onTap) {    return GestureDetector(      onTap: onTap,      child: Container(        width: 40,        height: 40,        decoration: BoxDecoration(          color: Colors.white,          borderRadius: BorderRadius.circular(8),          boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 8)],        ),        child: Icon(icon, color: AppTheme.textPrimary, size: 20),      ),    );  }  void _showEntryInfo(BuildContext context, EntryWithJournal item) {    showModalBottomSheet(      context: context,      backgroundColor: Colors.white,      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),      builder: (context) => Padding(        padding: const EdgeInsets.all(24),        child: Column(          mainAxisSize: MainAxisSize.min,          crossAxisAlignment: CrossAxisAlignment.start,          children: [            Row(              children: [                Container(                  width: 40,                  height: 40,                  decoration: BoxDecoration(color: AppTheme.terracottaLight, borderRadius: BorderRadius.circular(20)),                  child: const Icon(Icons.location_on, color: AppTheme.terracotta, size: 20),                ),                const SizedBox(width: 12),                Expanded(                  child: Column(                    crossAxisAlignment: CrossAxisAlignment.start,                    children: [                      Text(item.entry.locationName ?? 'Konum', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w500, color: AppTheme.textPrimary)),                      Text(item.journal.title, style: TextStyle(fontSize: 13, color: AppTheme.textSecondary)),                    ],                  ),                ),              ],            ),            if (item.entry.textContent != null) ...[              const SizedBox(height: 16),              Text(item.entry.textContent!, maxLines: 3, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 14, color: AppTheme.textSecondary, height: 1.5)),            ],            const SizedBox(height: 16),            SizedBox(              width: double.infinity,              child: ElevatedButton(                onPressed: () => Navigator.pop(context),                style: ElevatedButton.styleFrom(backgroundColor: AppTheme.terracotta, foregroundColor: Colors.white, elevation: 0, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),                child: const Text('Kapat'),              ),            ),          ],        ),      ),    );  }}class ExploreMapTab extends StatefulWidget {  const ExploreMapTab({super.key});  @override  State<ExploreMapTab> createState() => _ExploreMapTabState();}class _ExploreMapTabState extends State<ExploreMapTab> {  List<PublicLocation> _locations = [];  bool _isLoading = true;  final MapController _mapController = MapController();  double _zoom = 3;  @override  void initState() {    super.initState();    _loadPublicLocations();  }  Future<void> _loadPublicLocations() async {    try {      final journals = await JournalService.getPublicJournals();      List<PublicLocation> locations = [];      for (final journal in journals) {        final entries = await EntryService.getEntries(journal.id);        for (final entry in entries) {          if (entry.lat != null && entry.lng != null) {            locations.add(PublicLocation(entry: entry, journal: journal));          }        }      }      setState(() {        _locations = locations;        _isLoading = false;      });    } catch (e) {      setState(() => _isLoading = false);    }  }  void _zoomIn() {    _zoom = (_zoom + 1).clamp(1, 18);    _mapController.move(_mapController.camera.center, _zoom);  }  void _zoomOut() {    _zoom = (_zoom - 1).clamp(1, 18);    _mapController.move(_mapController.camera.center, _zoom);  }  @override  Widget build(BuildContext context) {    if (_isLoading) return const Center(child: CircularProgressIndicator(color: AppTheme.terracotta));    return Stack(      children: [        FlutterMap(          mapController: _mapController,          options: MapOptions(            initialCenter: _locations.isNotEmpty                ? LatLng(_locations.first.entry.lat!, _locations.first.entry.lng!)                : LatLng(41.0082, 28.9784),            initialZoom: _zoom,            onPositionChanged: (position, hasGesture) {              if (hasGesture) _zoom = position.zoom ?? _zoom;            },          ),          children: [            TileLayer(              urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',              userAgentPackageName: 'com.memorylane',            ),            MarkerLayer(              markers: _locations.map((item) => Marker(                point: LatLng(item.entry.lat!, item.entry.lng!),                width: 40,                height: 40,                child: GestureDetector(                  onTap: () => _showLocationInfo(context, item),                  child: Container(                    decoration: BoxDecoration(                      color: Colors.blue.shade400,                      borderRadius: BorderRadius.circular(20),                      boxShadow: [BoxShadow(color: Colors.blue.withOpacity(0.4), blurRadius: 8, offset: const Offset(0, 2))],                    ),                    child: const Icon(Icons.location_on, color: Colors.white, size: 20),                  ),                ),              )).toList(),            ),          ],        ),        if (_locations.isEmpty)          Center(            child: Container(              margin: const EdgeInsets.all(24),              padding: const EdgeInsets.all(24),              decoration: BoxDecoration(                color: Colors.white,                borderRadius: BorderRadius.circular(16),                boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 10)],              ),              child: Column(                mainAxisSize: MainAxisSize.min,                children: [                  Icon(Icons.explore_outlined, size: 48, color: AppTheme.textSecondary.withOpacity(0.4)),                  const SizedBox(height: 12),                  const Text('Henüz public konum yok', style: TextStyle(fontSize: 15, fontWeight: FontWeight.w500, color: AppTheme.textPrimary)),                ],              ),            ),          ),        Positioned(          bottom: 80,          right: 16,          child: Column(            children: [              _buildZoomButton(Icons.add, _zoomIn),              const SizedBox(height: 8),              _buildZoomButton(Icons.remove, _zoomOut),            ],          ),        ),        Positioned(          bottom: 16,          right: 16,          child: Container(            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),            decoration: BoxDecoration(              color: Colors.white,              borderRadius: BorderRadius.circular(20),              boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 8)],            ),            child: Text('${_locations.length} yer', style: TextStyle(fontSize: 13, color: AppTheme.textSecondary, fontWeight: FontWeight.w500)),          ),        ),      ],    );  }  Widget _buildZoomButton(IconData icon, VoidCallback onTap) {    return GestureDetector(      onTap: onTap,      child: Container(        width: 40,        height: 40,        decoration: BoxDecoration(          color: Colors.white,          borderRadius: BorderRadius.circular(8),          boxShadow: [BoxShadow(color: Colors.black.withOpacity(0.1), blurRadius: 8)],        ),        child: Icon(icon, color: AppTheme.textPrimary, size: 20),      ),    );  }  void _showLocationInfo(BuildContext context, PublicLocation item) {    showModalBottomSheet(      context: context,      backgroundColor: Colors.white,      shape: const RoundedRectangleBorder(borderRadius: BorderRadius.vertical(top: Radius.circular(20))),      builder: (context) => Padding(        padding: const EdgeInsets.all(24),        child: Column(          mainAxisSize: MainAxisSize.min,          crossAxisAlignment: CrossAxisAlignment.start,          children: [            Row(              children: [                Container(                  width: 40,                  height: 40,                  decoration: BoxDecoration(color: Colors.blue.shade50, borderRadius: BorderRadius.circular(20)),                  child: Icon(Icons.location_on, color: Colors.blue.shade400, size: 20),                ),                const SizedBox(width: 12),                Expanded(                  child: Column(                    crossAxisAlignment: CrossAxisAlignment.start,                    children: [                      Text(item.entry.locationName ?? 'Konum', style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w500, color: AppTheme.textPrimary)),                      Text(item.journal.title, style: TextStyle(fontSize: 13, color: AppTheme.textSecondary)),                      Text('@${item.journal.username ?? ''}', style: TextStyle(fontSize: 12, color: AppTheme.terracotta, fontWeight: FontWeight.w500)),                    ],                  ),                ),              ],            ),            if (item.entry.textContent != null) ...[              const SizedBox(height: 16),              Text(item.entry.textContent!, maxLines: 3, overflow: TextOverflow.ellipsis, style: TextStyle(fontSize: 14, color: AppTheme.textSecondary, height: 1.5)),            ],            const SizedBox(height: 16),            SizedBox(              width: double.infinity,              child: ElevatedButton(                onPressed: () => Navigator.pop(context),                style: ElevatedButton.styleFrom(backgroundColor: AppTheme.terracotta, foregroundColor: Colors.white, elevation: 0, shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12))),                child: const Text('Kapat'),              ),            ),          ],        ),      ),    );  }}class EntryWithJournal {  final Entry entry;  final Journal journal;  EntryWithJournal({required this.entry, required this.journal});}class PublicLocation {  final Entry entry;  final Journal journal;  PublicLocation({required this.entry, required this.journal});}